Definition g3w2_words_exit (ra sp gp tp t0 t1 s0 s1 a1 a2 a3 a4 a6 a7 s2 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (D n : Z) : machine_state -> Prop :=
  fun ms' => exists (t2' a0' a5' s3' s4' s5' : word) (m' : mem),
    ms' = MS (mkR a2 sp gp tp t0 t1 t2' s0 s1 a0' a1 s4' a3 a4 s8 a6 a7 s2 s3' a5' s5' s6 s7 ra s10 s9 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0x137708) fc None m' (seg_rom asegs)
    /\ munch [(D, D + 4 * n)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma g3w2_words : forall (k : nat) (j : Z)
    (sp gp tp t0 t2 s0 a0 a1 a3 a5 a7 s2 s3 s5 t5 : word) F fc (m : mem) (SA DA n sh rsh : Z),
  Z.of_nat k = n - j -> 0 <= j -> (1 <= k)%nat -> n < 2^26 ->
  0 < SA -> SA mod 4 = 0 -> SA + 4 * (n + 1) <= 2^47 -> 0 < DA -> DA mod 4 = 0 -> DA + 4 * n <= 2^47 ->
  (DA + 4 * n <= 0x7fff7000 \/ 0x10007fff8000 <= DA) ->
  0 <= sh < 32 -> 0 <= rsh < 32 ->
  wr_at asegs m SA (4 * (n + 1)) -> acc asegs m SA (4 * (n + 1)) -> wr_at asegs m DA (4 * n) -> acc asegs m DA (4 * n) -> mem_inv asegs m ->
  evt asegs (g3w2_words_exit (Z_to_bv 64 1) sp gp tp t0 (Z_to_bv 64 2147450880) s0 (Z_to_bv 64 rsh) a1 (Z_to_bv 64 DA) a3 (Z_to_bv 64 DA)
               (Z_to_bv 64 SA) a7 s2 (Z_to_bv 64 (-5)) (Z_to_bv 64 1) (Z_to_bv 64 1) (Z_to_bv 64 1) (Z_to_bv 64 31) (Z_to_bv 64 SA) (Z_to_bv 64 (n * 4))
               (Z_to_bv 64 32) t5 (Z_to_bv 64 sh) F fc m DA n)
    (MS (mkR (Z_to_bv 64 DA) sp gp tp t0 (Z_to_bv 64 2147450880) t2 s0 (Z_to_bv 64 rsh) a0 a1 (Z_to_bv 64 (4 * j)) a3 (Z_to_bv 64 DA) (Z_to_bv 64 1) (Z_to_bv 64 SA) a7 s2 s3 a5 s5 (Z_to_bv 64 (-5)) (Z_to_bv 64 1) (Z_to_bv 64 1) (Z_to_bv 64 31) (Z_to_bv 64 1) (Z_to_bv 64 SA) (Z_to_bv 64 (n * 4)) (Z_to_bv 64 32) t5 (Z_to_bv 64 sh))
        F (Z_to_bv 64 0x13760c) fc None m (seg_rom asegs)).
